// Error/mark machinery, ported from PyYAML's error.py.

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !'�\r\n  '.includes(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !'�\r\n  '.includes(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end);
    return ' '.repeat(indent) + head + snippet + tail + '\n' +
      ' '.repeat(indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'yaml.error.YAMLError';
    this.pyMessage = message;
  }

  toString() {
    return this.pyMessage;
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.name = 'yaml.error.MarkedYAMLError';
    this.context = context === undefined ? null : context;
    this.contextMark = contextMark === undefined ? null : contextMark;
    this.problem = problem === undefined ? null : problem;
    this.problemMark = problemMark === undefined ? null : problemMark;
    this.note = note === undefined ? null : note;
  }

  toString() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
        (this.problem === null || this.problemMark === null ||
         this.contextMark.name !== this.problemMark.name ||
         this.contextMark.line !== this.problemMark.line ||
         this.contextMark.column !== this.problemMark.column)) {
      lines.push(this.contextMark.toString());
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(this.problemMark.toString());
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

function makeMarked(clsName) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.name = clsName;
    }
  };
}

export const ReaderError = class extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.name = 'yaml.reader.ReaderError';
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
  }

  toString() {
    return `unacceptable character #x${this.character.codePointAt(0).toString(16).toUpperCase()}: ` +
      `${this.reason}\n  in "${this.streamName}", position ${this.position}`;
  }
};

export const ScannerError = makeMarked('yaml.scanner.ScannerError');
export const ParserError = makeMarked('yaml.parser.ParserError');
export const ComposerError = makeMarked('yaml.composer.ComposerError');
export const ConstructorError = makeMarked('yaml.constructor.ConstructorError');
export const EmitterError = class extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'yaml.emitter.EmitterError';
  }
};
export const SerializerError = class extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'yaml.serializer.SerializerError';
  }
};
export const RepresenterError = class extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'yaml.representer.RepresenterError';
  }
};

