import fs from 'node:fs';

const map = {
  '': '\\x85',
  ' ': '\\u2028',
  ' ': '\\u2029',
  '﻿': '\\ufeff',
};

for (const f of process.argv.slice(2)) {
  let s = fs.readFileSync(f, 'utf8');
  let out = '';
  for (const ch of s) out += (map[ch] !== undefined ? map[ch] : ch);
  fs.writeFileSync(f, out);
}

