// Character stream over a string, ported from PyYAML's reader.py.
// Operates on code points (Python str semantics) so astral chars count as one.

import { Mark, ReaderError } from './errors.mjs';

const LINE_BREAKS = '\n\x85  ';

function isPrintable(ch) {
  if (ch === '\t' || ch === '\n' || ch === '\r' || ch === '\x85') return true;
  const c = ch.codePointAt(0);
  if (c >= 0x20 && c <= 0x7e) return true;
  if (c >= 0xa0 && c <= 0xd7ff) return true;
  if (c >= 0xe000 && c <= 0xfffd) return true;
  if (c >= 0x10000 && c <= 0x10ffff) return true;
  return false;
}

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.chars = Array.from(text);
    this.checkPrintable(this.chars);
    // PyYAML terminates the buffer with '\0' once the stream is exhausted.
    this.chars.push('�');
    this.buffer = this.chars.join('');
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(chars) {
    for (let i = 0; i < chars.length; i++) {
      if (!isPrintable(chars[i])) {
        throw new ReaderError(this.name, i, chars[i], 'unicode',
          'special characters are not allowed');
      }
    }
  }

  peek(index = 0) {
    const p = this.pointer + index;
    if (p >= this.chars.length) return '�';
    return this.chars[p];
  }

  prefix(length = 1) {
    let out = '';
    for (let i = 0; i < length; i++) {
      const p = this.pointer + i;
      if (p >= this.chars.length) break;
      out += this.chars[p];
    }
    return out;
  }

  forward(length = 1) {
    let n = length;
    while (n > 0) {
      const ch = this.peek();
      this.pointer += 1;
      this.index += 1;
      if (LINE_BREAKS.includes(ch) || (ch === '\r' && this.peek() !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      n -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.pointer);
  }
}

