// Small helpers that emulate CPython string/number formatting primitives.

const SHORT_ESCAPES = {
  '\\': '\\\\',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
};

function escapeForRepr(ch) {
  if (SHORT_ESCAPES[ch] !== undefined) return SHORT_ESCAPES[ch];
  const c = ch.codePointAt(0);
  if (c < 0x20 || c === 0x7f) return '\\x' + hex(c, 2);
  if (c < 0x7f) return ch;
  // Python's repr() keeps printable non-ASCII characters as-is; the classes we
  // need it for (Cc/Cf/Cs/Co/Cn/Zl/Zp/Zs) are escaped.
  if (isNonPrintableUnicode(c)) {
    if (c <= 0xff) return '\\x' + hex(c, 2);
    if (c <= 0xffff) return '\\u' + hex(c, 4);
    return '\\U' + hex(c, 8);
  }
  return ch;
}

function isNonPrintableUnicode(c) {
  if (c >= 0x80 && c <= 0x9f) return true;
  if (c === 0xa0 || c === 0xad) return true;
  if (c === 0x2028 || c === 0x2029) return true;
  if (c >= 0x2000 && c <= 0x200f) return true;
  if (c === 0xfeff) return true;
  if (c >= 0xd800 && c <= 0xf8ff) return true;
  if (c >= 0xfff9 && c <= 0xfffb) return true;
  return false;
}

export function hex(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

// Python's repr() for a str value, used verbatim in YAML error messages.
export function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === quote) out += '\\' + ch;
    else out += escapeForRepr(ch);
  }
  return out + quote;
}

// Python's int(str, base) for the digit sets YAML needs.
export function parseIntBig(text, base) {
  return BigInt(base === 16 ? '0x' + text : base === 8 ? '0o' + text
    : base === 2 ? '0b' + text : text);
}

export function zeroPad(s, width) {
  let out = s;
  while (out.length < width) out = '0' + out;
  return out;
}

