// YAML tokenizer, ported from PyYAML's scanner.py.

import { ScannerError } from './errors.mjs';
import { pyRepr, parseIntBig } from './pyutil.mjs';
import {
  StreamStartToken, StreamEndToken, DirectiveToken, DocumentStartToken,
  DocumentEndToken, BlockSequenceStartToken, BlockMappingStartToken,
  BlockEndToken, FlowSequenceStartToken, FlowMappingStartToken,
  FlowSequenceEndToken, FlowMappingEndToken, KeyToken, ValueToken,
  BlockEntryToken, FlowEntryToken, AliasToken, AnchorToken, TagToken,
  ScalarToken,
} from './tokens.mjs';

const NULL_BL_T_LINEBR = '\0 \t\r\n\x85  ';
const NULL_BL_LINEBR = '\0 \r\n\x85  ';
const NULL_OR_LINEBR = '\0\r\n\x85  ';
const LINEBR = '\r\n\x85  ';
const SPACE_LINEBR = ' \r\n\x85  ';
const DIGITS = '0123456789';
const HEX_DIGITS = '0123456789ABCDEFabcdef';

const ESCAPE_REPLACEMENTS = {
  '0': '\0',
  a: '\x07',
  b: '\x08',
  t: '\t',
  '\t': '\t',
  n: '\n',
  v: '\x0b',
  f: '\x0c',
  r: '\r',
  e: '\x1b',
  ' ': ' ',
  '"': '"',
  '\\': '\\',
  N: '\x85',
  _: '\xa0',
  L: ' ',
  P: ' ',
};

const ESCAPE_CODES = { x: 2, u: 4, U: 8 };

function isAlphaNumeric(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_';
}

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(reader) {
    this.reader = reader;
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.fetchStreamStart();
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
  }

  // -- reader delegation ---------------------------------------------------

  peek(index = 0) { return this.reader.peek(index); }
  prefix(length = 1) { return this.reader.prefix(length); }
  forward(length = 1) { this.reader.forward(length); }
  getMark() { return this.reader.getMark(); }
  get column() { return this.reader.column; }
  get line() { return this.reader.line; }
  get index() { return this.reader.index; }

  // -- public token API ----------------------------------------------------

  checkToken(...choices) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      if (!choices.length) return true;
      for (const id of choices) {
        if (this.tokens[0].id === id) return true;
      }
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) return this.tokens[0];
    return null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (!this.tokens.length) return true;
    this.stalePossibleSimpleKeys();
    if (this.nextPossibleSimpleKey() === this.tokensTaken) return true;
    return false;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);
    const ch = this.peek();
    if (ch === '\0') return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && !this.flowLevel) return this.fetchLiteral();
    if (ch === '>' && !this.flowLevel) return this.fetchFolded();
    if (ch === "'") return this.fetchSingle();
    if (ch === '"') return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError('while scanning for the next token', null,
      `found character ${pyRepr(ch)} that cannot start any token`,
      this.getMark());
  }

  // -- simple keys ---------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = !this.flowLevel && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(tokenNumber, required, this.index, this.line,
        this.column, this.getMark());
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // -- indentation ---------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(new BlockEndToken(mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // -- fetchers ------------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(new StreamStartToken(mark, mark, 'utf-8'));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(new StreamEndToken(mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() { this.fetchDocumentIndicator(DocumentStartToken); }

  fetchDocumentEnd() { this.fetchDocumentIndicator(DocumentEndToken); }

  fetchDocumentIndicator(TokenClass) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowSequenceStart() { this.fetchFlowCollectionStart(FlowSequenceStartToken); }

  fetchFlowMappingStart() { this.fetchFlowCollectionStart(FlowMappingStartToken); }

  fetchFlowCollectionStart(TokenClass) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowSequenceEnd() { this.fetchFlowCollectionEnd(FlowSequenceEndToken); }

  fetchFlowMappingEnd() { this.fetchFlowCollectionEnd(FlowMappingEndToken); }

  fetchFlowCollectionEnd(TokenClass) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new TokenClass(startMark, endMark));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new FlowEntryToken(startMark, endMark));
  }

  fetchBlockEntry() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'sequence entries are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockSequenceStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new BlockEntryToken(startMark, endMark));
  }

  fetchKey() {
    if (!this.flowLevel) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null, 'mapping keys are not allowed here',
          this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(new BlockMappingStartToken(mark, mark));
      }
    }
    this.allowSimpleKey = false;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new KeyToken(startMark, endMark));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        new KeyToken(key.mark, key.mark));
      if (!this.flowLevel) {
        if (this.addIndent(key.column)) {
          this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
            new BlockMappingStartToken(key.mark, key.mark));
        }
      }
      this.allowSimpleKey = false;
    } else {
      if (!this.flowLevel) {
        if (!this.allowSimpleKey) {
          throw new ScannerError(null, null,
            'mapping values are not allowed here', this.getMark());
        }
      }
      if (!this.flowLevel) {
        if (this.addIndent(this.column)) {
          const mark = this.getMark();
          this.tokens.push(new BlockMappingStartToken(mark, mark));
        }
      }
      this.allowSimpleKey = true;
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(new ValueToken(startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AliasToken));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(AnchorToken));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() { this.fetchBlockScalar('|'); }

  fetchFolded() { this.fetchBlockScalar('>'); }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() { this.fetchFlowScalar("'"); }

  fetchDouble() { this.fetchFlowScalar('"'); }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // -- checkers ------------------------------------------------------------

  checkDirective() { return this.column === 0; }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---' &&
      NULL_BL_T_LINEBR.includes(this.peek(3));
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...' &&
      NULL_BL_T_LINEBR.includes(this.peek(3));
  }

  checkBlockEntry() { return NULL_BL_T_LINEBR.includes(this.peek(1)); }

  checkKey() {
    if (this.flowLevel) return true;
    return NULL_BL_T_LINEBR.includes(this.peek(1));
  }

  checkValue() {
    if (this.flowLevel) return true;
    return NULL_BL_T_LINEBR.includes(this.peek(1));
  }

  checkPlain() {
    const ch = this.peek();
    return !'\0 \t\r\n\x85  -?:,[]{}#&*!|>\'"%@`'.includes(ch) ||
      (!NULL_BL_T_LINEBR.includes(this.peek(1)) &&
        (ch === '-' || (!this.flowLevel && (ch === '?' || ch === ':'))));
  }

  // -- scanners ------------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === '﻿') this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === ' ') this.forward();
      if (this.peek() === '#') {
        while (!NULL_OR_LINEBR.includes(this.peek())) this.forward();
      }
      if (this.scanLineBreak()) {
        if (!this.flowLevel) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!NULL_OR_LINEBR.includes(this.peek())) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return new DirectiveToken(name, value, startMark, endMark);
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!NULL_BL_LINEBR.includes(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a %YAML directive', startMark,
        `expected a digit or '.', but found ${pyRepr(this.peek())}`,
        this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!NULL_BL_LINEBR.includes(this.peek())) {
      throw new ScannerError('while scanning a %YAML directive', startMark,
        `expected a digit or ' ', but found ${pyRepr(this.peek())}`,
        this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!(ch >= '0' && ch <= '9')) {
      throw new ScannerError('while scanning a %YAML directive', startMark,
        `expected a digit, but found ${pyRepr(ch)}`, this.getMark());
    }
    let length = 0;
    while (this.peek(length) >= '0' && this.peek(length) <= '9') length += 1;
    const value = Number(parseIntBig(this.prefix(length), 10));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === ' ') this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === ' ') this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== ' ') {
      throw new ScannerError('while scanning a TAG directive', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!NULL_BL_LINEBR.includes(ch)) {
      throw new ScannerError('while scanning a TAG directive', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!NULL_OR_LINEBR.includes(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!NULL_OR_LINEBR.includes(ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(TokenClass) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (!length) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!'\0 \t\r\n\x85  ?:,]}%@`'.includes(ch)) {
      throw new ScannerError(`while scanning an ${name}`, startMark,
        `expected alphabetic or numeric character, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    const endMark = this.getMark();
    return new TokenClass(value, startMark, endMark);
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          `expected '>', but found ${pyRepr(this.peek())}`, this.getMark());
      }
      this.forward();
    } else if (NULL_BL_T_LINEBR.includes(ch)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!NULL_BL_LINEBR.includes(ch)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!NULL_BL_LINEBR.includes(ch)) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    const value = [handle, suffix];
    const endMark = this.getMark();
    return new TagToken(value, startMark, endMark);
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);
    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let breaks;
    let indent;
    let endMark;
    if (increment === null) {
      const res = this.scanBlockScalarIndentation();
      breaks = res[0];
      const maxIndent = res[1];
      endMark = res[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
    }
    let lineBreak = '';
    while (this.column === indent && this.peek() !== '\0') {
      for (const b of breaks) chunks.push(b);
      const leadingNonSpace = !' \t'.includes(this.peek());
      let length = 0;
      while (!NULL_OR_LINEBR.includes(this.peek(length))) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
      if (this.column === indent && this.peek() !== '\0') {
        if (folded && lineBreak === '\n' && leadingNonSpace &&
            !' \t'.includes(this.peek())) {
          if (!breaks.length) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }
    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) for (const b of breaks) chunks.push(b);
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (DIGITS.includes(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (DIGITS.includes(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!NULL_BL_LINEBR.includes(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!NULL_OR_LINEBR.includes(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!NULL_OR_LINEBR.includes(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`,
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (SPACE_LINEBR.includes(this.peek())) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (LINEBR.includes(this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    for (const c of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(c);
    while (this.peek() !== quote) {
      for (const c of this.scanFlowScalarSpaces(double, startMark)) chunks.push(c);
      for (const c of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(c);
    }
    this.forward();
    const endMark = this.getMark();
    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      while (!'\'"\\\0 \t\r\n\x85  '.includes(this.peek(length))) {
        length += 1;
      }
      if (length) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === "'" && this.peek(1) === "'") {
        chunks.push("'");
        this.forward(2);
      } else if ((double && ch === "'") || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (Object.prototype.hasOwnProperty.call(ESCAPE_REPLACEMENTS, ch)) {
          chunks.push(ESCAPE_REPLACEMENTS[ch]);
          this.forward();
        } else if (Object.prototype.hasOwnProperty.call(ESCAPE_CODES, ch)) {
          length = ESCAPE_CODES[ch];
          this.forward();
          for (let k = 0; k < length; k++) {
            if (!HEX_DIGITS.includes(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar',
                startMark,
                `expected escape sequence of ${length} hexadecimal numbers, but found ${pyRepr(this.peek(k))}`,
                this.getMark());
            }
          }
          const code = Number(parseIntBig(this.prefix(length), 16));
          chunks.push(fromCodePoint(code));
          this.forward(length);
        } else if (LINEBR.includes(ch)) {
          this.scanLineBreak();
          for (const c of this.scanFlowScalarBreaks(double, startMark)) chunks.push(c);
        } else {
          throw new ScannerError('while scanning a double-quoted scalar',
            startMark, `found unknown escape character ${pyRepr(ch)}`,
            this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (' \t'.includes(this.peek(length))) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === '\0') {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (LINEBR.includes(ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (!breaks.length) chunks.push(' ');
      for (const b of breaks) chunks.push(b);
