    ch = this.peek(length);
    if (ch !== ' ') {
      while (isAlphaNumeric(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(`while scanning a ${name}`, startMark,
          `expected '!', but found ${pyRepr(ch)}`, this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
        (ch >= 'a' && ch <= 'z') || "-;/?:@&=+$,_.!~*'()[]%".includes(ch)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (!chunks.length) {
      throw new ScannerError(`while parsing a ${name}`, startMark,
        `expected URI, but found ${pyRepr(ch)}`, this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k++) {
        if (!HEX_DIGITS.includes(this.peek(k))) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            `expected URI escape sequence of 2 hexadecimal numbers, but found ${pyRepr(this.peek(k))}`,
            this.getMark());
        }
      }
      codes.push(Number(parseIntBig(this.prefix(2), 16)));
      this.forward(2);
    }
    const decoded = decodeUtf8Strict(codes);
    if (decoded === null) {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        'invalid utf-8 byte sequence', mark);
    }
    return decoded;
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === '\x85') {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (ch === ' ' || ch === ' ') {
      this.forward();
      return ch;
    }
    return '';
  }
}

function fromCodePoint(code) {
  if (code > 0x10ffff) {
    throw new RangeError('chr() arg not in range(0x110000)');
  }
  if (code >= 0xd800 && code <= 0xdfff) {
    // Lone surrogate: Python keeps it, JS needs the raw code unit.
    return String.fromCharCode(code);
  }
  return String.fromCodePoint(code);
}

function decodeUtf8Strict(bytes) {
  const decoder = new TextDecoder('utf-8', { fatal: true });
  try {
    return decoder.decode(new Uint8Array(bytes));
  } catch {
    return null;
  }
}

