// Event producer, ported from PyYAML's parser.py.
// Parser states are stored as method names so they can be pushed on a stack.

import { ParserError } from './errors.mjs';
import { pyRepr } from './pyutil.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

const DEFAULT_TAGS = { '!': '!', '!!': 'tag:yaml.org,2002:' };

export class Parser {
  constructor(scanner) {
    this.scanner = scanner;
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  checkToken(...choices) { return this.scanner.checkToken(...choices); }
  peekToken() { return this.scanner.peekToken(); }
  getToken() { return this.scanner.getToken(); }

  runState() { return this[this.state](); }

  checkEvent(...choices) {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.runState();
    }
    if (this.currentEvent !== null) {
      if (!choices.length) return true;
      for (const kind of choices) {
        if (this.currentEvent.kind === kind) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.runState();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this.runState();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // -- stream/document -----------------------------------------------------

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark,
      token.encoding);
    this.state = 'parseImplicitDocumentStart';
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken('<directive>', '<document start>', '<stream end>')) {
      this.tagHandles = new Map(Object.entries(DEFAULT_TAGS));
      const token = this.peekToken();
      const startMark = token.startMark;
      const event = new DocumentStartEvent(startMark, startMark, false);
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNode';
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken('<document end>')) this.getToken();
    let event;
    if (!this.checkToken('<stream end>')) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken('<document start>')) {
        throw new ParserError(null, null,
          `expected '<document start>', but found ${pyRepr(this.peekToken().id)}`,
          this.peekToken().startMark);
      }
      token = this.getToken();
      event = new DocumentStartEvent(startMark, token.endMark, true, version, tags);
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
    } else {
      const token = this.getToken();
      event = new StreamEndEvent(token.startMark, token.endMark);
      this.state = null;
    }
    return event;
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = token.startMark;
    let explicit = false;
    if (this.checkToken('<document end>')) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);
    this.state = 'parseDocumentStart';
    return event;
  }

  parseDocumentContent() {
    if (this.checkToken('<directive>', '<document start>', '<document end>',
      '<stream end>')) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken('<directive>')) {
      const token = this.getToken();
      if (token.tokenName === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive',
            token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.tokenName === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(null, null,
            `duplicate tag handle ${pyRepr(handle)}`, token.startMark);
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    let value;
    if (this.tagHandles.size) value = [this.yamlVersion, new Map(this.tagHandles)];
    else value = [this.yamlVersion, null];
    for (const key of Object.keys(DEFAULT_TAGS)) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, DEFAULT_TAGS[key]);
    }
    return value;
  }

  // -- nodes ---------------------------------------------------------------

  parseBlockNode() { return this.parseNode(true, false); }

  parseFlowNode() { return this.parseNode(false, false); }

  parseBlockNodeOrIndentlessSequence() { return this.parseNode(true, true); }

  parseNode(block = false, indentlessSequence = false) {
    if (this.checkToken('<alias>')) {
      const token = this.getToken();
      const event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
      return event;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken('<anchor>')) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken('<tag>')) {
        token = this.getToken();
