// Implicit tag resolution for YAML 1.1, ported from PyYAML's resolver.py.
// PyYAML drives this with regular expressions; the equivalent matchers here are
// hand-written character walks.

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

const BOOL_VALUES = new Set([
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
]);

const isDigit = (ch) => ch >= '0' && ch <= '9';
const isHexDigit = (ch) => isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');

// A minimal cursor used to express the original regexps as linear scans.
class Cur {
  constructor(s) {
    this.s = s;
    this.i = 0;
  }

  get done() { return this.i >= this.s.length; }
  peek(k = 0) { return this.i + k < this.s.length ? this.s[this.i + k] : ''; }

  eat(ch) {
    if (this.peek() === ch) { this.i += 1; return true; }
    return false;
  }

  eatAny(chars) {
    if (this.i < this.s.length && chars.includes(this.peek())) { this.i += 1; return true; }
    return false;
  }

  // Consumes characters accepted by `pred`, returns how many.
  eatWhile(pred) {
    let n = 0;
    while (this.i < this.s.length && pred(this.peek())) { this.i += 1; n += 1; }
    return n;
  }

  eatLiteral(text) {
    if (this.s.startsWith(text, this.i)) { this.i += text.length; return true; }
    return false;
  }
}

function matchBool(value) {
  return BOOL_VALUES.has(value);
}

// ^(?:[-+]?(?:[0-9][0-9_]*)\.[0-9_]*(?:[eE][-+][0-9]+)?
//   |\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?
//   |[-+]?[0-9][0-9_]*(?::[0-5]?[0-9])+\.[0-9_]*
//   |[-+]?\.(?:inf|Inf|INF)
//   |\.(?:nan|NaN|NAN))$
function matchFloat(value) {
  return floatDecimal(value) || floatDotLeading(value) || floatSexagesimal(value) ||
    floatInf(value) || floatNan(value);
}

const isDigitOrUnderscore = (ch) => isDigit(ch) || ch === '_';

function floatDecimal(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!isDigit(c.peek())) return false;
  c.i += 1;
  c.eatWhile(isDigitOrUnderscore);
  if (!c.eat('.')) return false;
  c.eatWhile(isDigitOrUnderscore);
  if (c.done) return true;
  return matchSignedExponent(c) && c.done;
}

function floatDotLeading(value) {
  const c = new Cur(value);
  if (!c.eat('.')) return false;
  if (!isDigit(c.peek())) return false;
  c.i += 1;
  c.eatWhile(isDigitOrUnderscore);
  if (c.done) return true;
  return matchSignedExponent(c) && c.done;
}

function matchSignedExponent(c) {
  if (!c.eatAny('eE')) return false;
  if (!c.eatAny('-+')) return false;
  return c.eatWhile(isDigit) > 0;
}

function floatSexagesimal(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!isDigit(c.peek())) return false;
  c.i += 1;
  c.eatWhile(isDigitOrUnderscore);
  let groups = 0;
  while (c.peek() === ':') {
    c.i += 1;
    if (!matchSexagesimalGroup(c)) return false;
    groups += 1;
  }
  if (!groups) return false;
  if (!c.eat('.')) return false;
  c.eatWhile(isDigitOrUnderscore);
  return c.done;
}

// (?::[0-5]?[0-9]) -- the ':' is consumed by the caller.
function matchSexagesimalGroup(c) {
  if (c.peek() >= '0' && c.peek() <= '5' && isDigit(c.peek(1))) {
    c.i += 2;
    return true;
  }
  if (isDigit(c.peek())) {
    c.i += 1;
    return true;
  }
  return false;
}

function floatInf(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!c.eat('.')) return false;
  if (!(c.eatLiteral('inf') || c.eatLiteral('Inf') || c.eatLiteral('INF'))) return false;
  return c.done;
}

function floatNan(value) {
  const c = new Cur(value);
  if (!c.eat('.')) return false;
  if (!(c.eatLiteral('nan') || c.eatLiteral('NaN') || c.eatLiteral('NAN'))) return false;
  return c.done;
}

// ^(?:[-+]?0b[0-1_]+
//   |[-+]?0[0-7_]+
//   |[-+]?(?:0|[1-9][0-9_]*)
//   |[-+]?0x[0-9a-fA-F_]+
//   |[-+]?[1-9][0-9_]*(?::[0-5]?[0-9])+)$
function matchInt(value) {
  return intBinary(value) || intOctal(value) || intDecimal(value) ||
    intHex(value) || intSexagesimal(value);
}

function intBinary(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!c.eatLiteral('0b')) return false;
  if (c.eatWhile((ch) => ch === '0' || ch === '1' || ch === '_') === 0) return false;
  return c.done;
}

function intOctal(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!c.eat('0')) return false;
  if (c.eatWhile((ch) => (ch >= '0' && ch <= '7') || ch === '_') === 0) return false;
  return c.done;
}

function intDecimal(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (c.eat('0')) return c.done;
  if (!(c.peek() >= '1' && c.peek() <= '9')) return false;
  c.i += 1;
  c.eatWhile(isDigitOrUnderscore);
  return c.done;
}

function intHex(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!c.eatLiteral('0x')) return false;
  if (c.eatWhile((ch) => isHexDigit(ch) || ch === '_') === 0) return false;
  return c.done;
}

function intSexagesimal(value) {
  const c = new Cur(value);
  c.eatAny('-+');
  if (!(c.peek() >= '1' && c.peek() <= '9')) return false;
  c.i += 1;
  c.eatWhile(isDigitOrUnderscore);
  let groups = 0;
  while (c.peek() === ':') {
    c.i += 1;
    if (!matchSexagesimalGroup(c)) return false;
    groups += 1;
  }
  return groups > 0 && c.done;
}

function matchMerge(value) { return value === '<<'; }

function matchNull(value) {
  return value === '~' || value === 'null' || value === 'Null' ||
    value === 'NULL' || value === '';
}

// ^(?:[0-9]{4}-[0-9]{2}-[0-9]{2}
//   |[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}(?:[Tt]|[ \t]+)[0-9]{1,2}
//    :[0-9]{2}:[0-9]{2}(?:\.[0-9]*)?(?:[ \t]*(?:Z|[-+][0-9]{1,2}(?::[0-9]{2})?))?)$
function matchTimestamp(value) {
  return timestampDateOnly(value) || timestampFull(value);
}

function eatDigits(c, min, max) {
  let n = 0;
  while (n < max && isDigit(c.peek())) { c.i += 1; n += 1; }
  return n >= min;
}

function timestampDateOnly(value) {
  const c = new Cur(value);
  if (!eatDigits(c, 4, 4)) return false;
  if (!c.eat('-')) return false;
  if (!eatDigits(c, 2, 2)) return false;
  if (!c.eat('-')) return false;
  if (!eatDigits(c, 2, 2)) return false;
  return c.done;
}

function timestampFull(value) {
  const c = new Cur(value);
  if (!eatDigits(c, 4, 4)) return false;
  if (!c.eat('-')) return false;
  if (!eatDigits(c, 1, 2)) return false;
  if (!c.eat('-')) return false;
  if (!eatDigits(c, 1, 2)) return false;
  if (c.peek() === 'T' || c.peek() === 't') {
    c.i += 1;
  } else if (c.eatWhile((ch) => ch === ' ' || ch === '\t') === 0) {
    return false;
  }
  if (!eatDigits(c, 1, 2)) return false;
  if (!c.eat(':')) return false;
  if (!eatDigits(c, 2, 2)) return false;
  if (!c.eat(':')) return false;
  if (!eatDigits(c, 2, 2)) return false;
  if (c.eat('.')) c.eatWhile(isDigit);
  if (c.done) return true;
  c.eatWhile((ch) => ch === ' ' || ch === '\t');
  if (c.done) return true;
  if (c.eat('Z')) return c.done;
  if (!c.eatAny('-+')) return false;
  if (!eatDigits(c, 1, 2)) return false;
  if (c.eat(':')) {
    if (!eatDigits(c, 2, 2)) return false;
  }
  return c.done;
}

function matchValueTag(value) { return value === '='; }

function matchYamlTag(value) {
  return value === '!' || value === '&' || value === '*';
}

// Registration order from resolver.py; each entry lists the first characters
// PyYAML indexes the resolver under ('' stands for the empty scalar).
const IMPLICIT_RESOLVERS = [
  ['tag:yaml.org,2002:bool', matchBool, 'yYnNtTfFoO'],
  ['tag:yaml.org,2002:float', matchFloat, '-+0123456789.'],
  ['tag:yaml.org,2002:int', matchInt, '-+0123456789'],
  ['tag:yaml.org,2002:merge', matchMerge, '<'],
  ['tag:yaml.org,2002:null', matchNull, '~nN\0'],
  ['tag:yaml.org,2002:timestamp', matchTimestamp, '0123456789'],
  ['tag:yaml.org,2002:value', matchValueTag, '='],
  ['tag:yaml.org,2002:yaml', matchYamlTag, '!&*'],
];

export class Resolver {
  // `kind` is 'scalar' | 'sequence' | 'mapping'; `implicit` is [plain, nonPlain].
  resolve(kind, value, implicit) {
    if (kind === 'scalar' && implicit[0]) {
      // '\0' stands in for PyYAML's '' key covering the empty scalar.
      const first = value === '' ? '\0' : value[0];
      for (const [tag, match, chars] of IMPLICIT_RESOLVERS) {
        if (!chars.includes(first)) continue;
        if (match(value)) return tag;
      }
    }
    if (kind === 'scalar') return DEFAULT_SCALAR_TAG;
    if (kind === 'sequence') return DEFAULT_SEQUENCE_TAG;
    return DEFAULT_MAPPING_TAG;
  }

  descendResolver() {}

  ascendResolver() {}
}

