// JavaScript stand-ins for the Python values PyYAML produces, plus the
// CPython behaviours the dumper depends on: repr(float), dict key identity,
// rich comparison for sorted(), and datetime formatting.
//
// Mapping: None -> null, bool -> boolean, int -> BigInt, float -> number,
// str -> string, and the classes below for everything else.

import { zeroPad } from './pyutil.mjs';

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyDict {
  constructor() {
    this.map = new Map(); // hash key -> [key, value]
  }

  get size() { return this.map.size; }

  set(key, value) {
    const h = hashKey(key);
    const existing = this.map.get(h);
    if (existing !== undefined) existing[1] = value;
    else this.map.set(h, [key, value]);
  }

  has(key) { return this.map.has(hashKey(key)); }

  get(key) {
    const entry = this.map.get(hashKey(key));
    return entry === undefined ? undefined : entry[1];
  }

  items() { return Array.from(this.map.values()); }
}

export class PySet {
  constructor() {
    this.map = new Map(); // hash key -> key
  }

  get size() { return this.map.size; }

  add(key) {
    const h = hashKey(key);
    if (!this.map.has(h)) this.map.set(h, key);
  }

  values() { return Array.from(this.map.values()); }
}

export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return `${zeroPad(String(this.year), 4)}-${zeroPad(String(this.month), 2)}-` +
      `${zeroPad(String(this.day), 2)}`;
  }
}

export class PyDateTime {
  // offsetMinutes is null for naive datetimes.
  constructor(year, month, day, hour, minute, second, microsecond, offsetMinutes) {
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.offsetMinutes = offsetMinutes === undefined ? null : offsetMinutes;
  }

  isoformat(sep = 'T') {
    let out = `${zeroPad(String(this.year), 4)}-${zeroPad(String(this.month), 2)}-` +
      `${zeroPad(String(this.day), 2)}${sep}` +
      `${zeroPad(String(this.hour), 2)}:${zeroPad(String(this.minute), 2)}:` +
      `${zeroPad(String(this.second), 2)}`;
    if (this.microsecond) out += '.' + zeroPad(String(this.microsecond), 6);
    if (this.offsetMinutes !== null) {
      const sign = this.offsetMinutes < 0 ? '-' : '+';
      const abs = Math.abs(this.offsetMinutes);
      out += `${sign}${zeroPad(String(Math.floor(abs / 60)), 2)}:` +
        `${zeroPad(String(abs % 60), 2)}`;
    }
    return out;
  }
}

export class PyUnhashableError extends Error {
  constructor(typeName) {
    super(`unhashable type: '${typeName}'`);
    this.typeName = typeName;
  }
}

export function typeName(value) {
  if (value === null) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'bigint') return 'int';
  if (typeof value === 'number') return 'float';
  if (typeof value === 'string') return 'str';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyTuple) return 'tuple';
  if (value instanceof PyDict) return 'dict';
  if (value instanceof PySet) return 'set';
  if (value instanceof PyBytes) return 'bytes';
  if (value instanceof PyDateTime) return 'datetime.datetime';
  if (value instanceof PyDate) return 'datetime.date';
  return 'object';
}

let nanCounter = 0;

// A string that collides exactly when Python dict keys would compare equal.
export function hashKey(value) {
  if (value === null) return 'N';
  if (typeof value === 'boolean') return 'i' + (value ? '1' : '0');
  if (typeof value === 'bigint') return 'i' + value.toString();
  if (typeof value === 'number') {
    if (Number.isNaN(value)) { nanCounter += 1; return 'nan#' + nanCounter; }
    if (Number.isInteger(value) && Math.abs(value) < 1e21) {
      return 'i' + BigInt(value).toString();
    }
