// SafeConstructor: node graph -> Python values. Ported from PyYAML's
// constructor.py (BaseConstructor + SafeConstructor).

import { ConstructorError } from './errors.mjs';
import { pyRepr, parseIntBig } from './pyutil.mjs';
import {
  PyBytes, PyTuple, PyDict, PySet, PyDate, PyDateTime,
  isHashable, PyUnhashableError,
} from './pytypes.mjs';

export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

const T = {
  null: 'tag:yaml.org,2002:null',
  bool: 'tag:yaml.org,2002:bool',
  int: 'tag:yaml.org,2002:int',
  float: 'tag:yaml.org,2002:float',
  binary: 'tag:yaml.org,2002:binary',
  timestamp: 'tag:yaml.org,2002:timestamp',
  omap: 'tag:yaml.org,2002:omap',
  pairs: 'tag:yaml.org,2002:pairs',
  set: 'tag:yaml.org,2002:set',
  str: 'tag:yaml.org,2002:str',
  seq: 'tag:yaml.org,2002:seq',
  map: 'tag:yaml.org,2002:map',
  merge: 'tag:yaml.org,2002:merge',
  value: 'tag:yaml.org,2002:value',
};

const BOOL_VALUES = {
  yes: true, no: false, true: true, false: false, on: true, off: false,
};

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function checkDateParts(year, month, day) {
  if (month < 1 || month > 12) throw new PyValueError('month must be in 1..12');
  let maxDay = DAYS_IN_MONTH[month - 1];
  if (month === 2 && isLeap(year)) maxDay = 29;
  if (day < 1 || day > maxDay) {
    throw new PyValueError('day is out of range for month');
  }
}

function checkTimeParts(hour, minute, second) {
  if (hour < 0 || hour > 23) throw new PyValueError('hour must be in 0..23');
  if (minute < 0 || minute > 59) throw new PyValueError('minute must be in 0..59');
  if (second < 0 || second > 59) throw new PyValueError('second must be in 0..59');
}

export class SafeConstructor {
  constructor(composer) {
    this.composer = composer;
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

  getSingleData() {
    const node = this.composer.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return null;
  }

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const fill of generators) fill();
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructorFor(tag) {
    switch (tag) {
      case T.null: return (n) => this.constructYamlNull(n);
      case T.bool: return (n) => this.constructYamlBool(n);
      case T.int: return (n) => this.constructYamlInt(n);
      case T.float: return (n) => this.constructYamlFloat(n);
      case T.binary: return (n) => this.constructYamlBinary(n);
      case T.timestamp: return (n) => this.constructYamlTimestamp(n);
      case T.omap: return (n) => this.constructYamlOmap(n);
      case T.pairs: return (n) => this.constructYamlPairs(n);
      case T.set: return (n) => this.constructYamlSet(n);
      case T.str: return (n) => this.constructYamlStr(n);
      case T.seq: return (n) => this.constructYamlSeq(n);
      case T.map: return (n) => this.constructYamlMap(n);
      default: return null;
    }
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) return this.constructedObjects.get(node);
    let oldDeep = null;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null,
        'found unconstructable recursive node', node.startMark);
    }
    this.recursiveObjects.set(node, null);
    const constructor = this.constructorFor(node.tag);
    let result;
    if (constructor === null) {
      // SafeConstructor registers construct_undefined for the null tag key.
      result = this.constructUndefined(node);
    } else {
      result = constructor(node);
    }
    let data;
    if (result !== null && typeof result === 'object' && result.isGenerator) {
      data = result.value;
      if (this.deepConstruct) result.fill();
      else this.stateGenerators.push(result.fill);
    } else {
      data = result;
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  // -- base构造 helpers ----------------------------------------------------

  constructScalar(node) {
    if (node.kind === 'mapping') {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === T.value) return this.constructScalar(valueNode);
      }
    }
    if (node.kind !== 'scalar') {
      throw new ConstructorError(null, null,
        `expected a scalar node, but found ${node.kind}`, node.startMark);
