  }

  constructYamlTimestamp(node) {
    const value = this.constructScalar(node);
    const m = parseTimestamp(value);
    if (m === null) {
      throw new PyValueError(
        `'NoneType' object has no attribute 'groupdict'`);
    }
    const year = m.year;
    const month = m.month;
    const day = m.day;
    checkDateParts(year, month, day);
    if (m.hour === null) return new PyDate(year, month, day);
    checkTimeParts(m.hour, m.minute, m.second);
    let fraction = 0;
    if (m.fraction) {
      let digits = m.fraction.slice(0, 6);
      while (digits.length < 6) digits += '0';
      fraction = Number(digits);
      if (m.fraction.length > 6 && Number(m.fraction[6]) > 4) fraction += 1;
    }
    let offsetMinutes = null;
    if (m.tzSign) {
      const tzHour = m.tzHour;
      const tzMinute = m.tzMinute === null ? 0 : m.tzMinute;
      offsetMinutes = tzHour * 60 + tzMinute;
      if (m.tzSign === '-') offsetMinutes = -offsetMinutes;
    } else if (m.tz) {
      offsetMinutes = 0;
    }
    return new PyDateTime(year, month, day, m.hour, m.minute, m.second,
      fraction, offsetMinutes);
  }

  constructYamlOmap(node) {
    const omap = [];
    return {
      isGenerator: true,
      value: omap,
      fill: () => {
        if (node.kind !== 'sequence') {
          throw new ConstructorError('while constructing an ordered map',
            node.startMark, `expected a sequence, but found ${node.kind}`,
            node.startMark);
        }
        for (const subnode of node.value) {
          if (subnode.kind !== 'mapping') {
            throw new ConstructorError('while constructing an ordered map',
              node.startMark,
              `expected a mapping of length 1, but found ${subnode.kind}`,
              subnode.startMark);
          }
          if (subnode.value.length !== 1) {
            throw new ConstructorError('while constructing an ordered map',
              node.startMark,
              `expected a single mapping item, but found ${subnode.value.length} items`,
              subnode.startMark);
          }
          const [keyNode, valueNode] = subnode.value[0];
          const key = this.constructObject(keyNode);
          const value = this.constructObject(valueNode);
          omap.push(new PyTuple([key, value]));
        }
      },
    };
  }

  constructYamlPairs(node) {
    const pairs = [];
    return {
      isGenerator: true,
      value: pairs,
      fill: () => {
        if (node.kind !== 'sequence') {
          throw new ConstructorError('while constructing pairs', node.startMark,
            `expected a sequence, but found ${node.kind}`, node.startMark);
        }
        for (const subnode of node.value) {
          if (subnode.kind !== 'mapping') {
            throw new ConstructorError('while constructing pairs', node.startMark,
              `expected a mapping of length 1, but found ${subnode.kind}`,
              subnode.startMark);
          }
          if (subnode.value.length !== 1) {
            throw new ConstructorError('while constructing pairs', node.startMark,
              `expected a single mapping item, but found ${subnode.value.length} items`,
              subnode.startMark);
          }
          const [keyNode, valueNode] = subnode.value[0];
          const key = this.constructObject(keyNode);
          const value = this.constructObject(valueNode);
          pairs.push(new PyTuple([key, value]));
        }
      },
    };
  }

  constructYamlSet(node) {
    const data = new PySet();
    return {
      isGenerator: true,
      value: data,
      fill: () => {
        const value = this.constructMapping(node);
        for (const [key] of value.items()) data.add(key);
      },
    };
  }

  constructYamlStr(node) { return this.constructScalar(node); }

  constructYamlSeq(node) {
    const data = [];
    return {
      isGenerator: true,
      value: data,
      fill: () => {
        for (const item of this.constructSequence(node)) data.push(item);
      },
    };
  }

  constructYamlMap(node) {
    const data = new PyDict();
    return {
      isGenerator: true,
      value: data,
      fill: () => {
        const value = this.constructMapping(node);
        for (const [key, val] of value.items()) data.set(key, val);
      },
    };
  }

  constructUndefined(node) {
    throw new ConstructorError(null, null,
      `could not determine a constructor for the tag ${pyRepr(node.tag)}`,
      node.startMark);
  }
}

export { PyUnhashableError };

// ^(?P<year>[0-9]{4})-(?P<month>[0-9]{1,2})-(?P<day>[0-9]{1,2})
//  (?:(?:[Tt]|[ \t]+)(?P<hour>[0-9]{1,2}):(?P<minute>[0-9]{2}):(?P<second>[0-9]{2})
//  (?:\.(?P<fraction>[0-9]*))?
//  (?:[ \t]*(?P<tz>Z|(?P<tz_sign>[-+])(?P<tz_hour>[0-9]{1,2})
//  (?::(?P<tz_minute>[0-9]{2}))?))?)?$
function parseTimestamp(text) {
  let i = 0;
  const isDigit = (ch) => ch >= '0' && ch <= '9';
  const at = (k) => (i + k < text.length ? text[i + k] : '');
  const takeDigits = (min, max) => {
    let s = '';
    while (s.length < max && isDigit(at(0))) { s += text[i]; i += 1; }
    return s.length >= min ? s : null;
  };
  const year = takeDigits(4, 4);
  if (year === null || at(0) !== '-') return null;
  i += 1;
  const month = takeDigits(1, 2);
  if (month === null || at(0) !== '-') return null;
  i += 1;
  const day = takeDigits(1, 2);
  if (day === null) return null;
  const out = {
    year: Number(year), month: Number(month), day: Number(day),
    hour: null, minute: null, second: null, fraction: null,
    tz: null, tzSign: null, tzHour: null, tzMinute: null,
  };
  if (i === text.length) return out;
  const rest = i;
  if (at(0) === 'T' || at(0) === 't') {
    i += 1;
  } else if (at(0) === ' ' || at(0) === '\t') {
    while (at(0) === ' ' || at(0) === '\t') i += 1;
  } else {
    return null;
  }
  if (i === rest) return null;
  const hour = takeDigits(1, 2);
  if (hour === null || at(0) !== ':') return null;
  i += 1;
  const minute = takeDigits(2, 2);
  if (minute === null || at(0) !== ':') return null;
  i += 1;
  const second = takeDigits(2, 2);
  if (second === null) return null;
  out.hour = Number(hour);
  out.minute = Number(minute);
  out.second = Number(second);
  if (at(0) === '.') {
    i += 1;
    let frac = '';
    while (isDigit(at(0))) { frac += text[i]; i += 1; }
    out.fraction = frac;
  }
  if (i === text.length) return out;
  const beforeTz = i;
  while (at(0) === ' ' || at(0) === '\t') i += 1;
  if (at(0) === 'Z') {
    i += 1;
    out.tz = 'Z';
    return i === text.length ? out : null;
  }
  if (at(0) === '-' || at(0) === '+') {
    const sign = text[i];
    i += 1;
    const tzHour = takeDigits(1, 2);
    if (tzHour === null) return null;
    let tzMinute = null;
    if (at(0) === ':') {
      i += 1;
      tzMinute = takeDigits(2, 2);
      if (tzMinute === null) return null;
    }
    out.tz = text.slice(beforeTz).trim();
    out.tzSign = sign;
    out.tzHour = Number(tzHour);
    out.tzMinute = tzMinute === null ? null : Number(tzMinute);
    return i === text.length ? out : null;
  }
  return null;
}

const B64_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

// base64.decodebytes(): ignores characters outside the alphabet, rejects
// truncated groups.
function base64Decode(text) {
  const values = [];
  for (const ch of text) {
    if (ch === '=') break;
    const idx = B64_ALPHABET.indexOf(ch);
    if (idx >= 0) values.push(idx);
  }
  if (values.length % 4 === 1) return null;
  const out = [];
  for (let i = 0; i + 1 < values.length; i += 4) {
    const chunk = values.slice(i, i + 4);
    let bits = 0;
    for (let k = 0; k < chunk.length; k++) bits |= chunk[k] << (18 - 6 * k);
    out.push((bits >> 16) & 0xff);
    if (chunk.length >= 3) out.push((bits >> 8) & 0xff);
    if (chunk.length >= 4) out.push(bits & 0xff);
  }
  return new Uint8Array(out);
}

