import { safeLoad } from '/output/lib/loader.mjs';
import { PyDict, PySet, PyTuple, PyBytes, PyDate, PyDateTime, pyFloatRepr } from '/output/lib/pytypes.mjs';

function show(v) {
  if (v === null) return 'None';
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return pyFloatRepr(v);
  if (typeof v === 'string') return JSON2(v);
  if (Array.isArray(v)) return '[' + v.map(show).join(', ') + ']';
  if (v instanceof PyTuple) return '(' + v.items.map(show).join(', ') + ')';
  if (v instanceof PyDict) return '{' + v.items().map(([k, val]) => show(k) + ': ' + show(val)).join(', ') + '}';
  if (v instanceof PySet) return '{' + v.values().map(show).join(', ') + '}';
  if (v instanceof PyBytes) return 'b' + JSON2(Array.from(v.bytes).map(b => String.fromCharCode(b)).join(''));
  if (v instanceof PyDateTime) return 'datetime(' + v.isoformat(' ') + ')';
  if (v instanceof PyDate) return 'date(' + v.isoformat() + ')';
  return String(v);
}

function JSON2(s) {
  let out = "'";
  for (const ch of s) {
    if (ch === '\n') out += '\\n';
    else if (ch === '\t') out += '\\t';
    else if (ch === "'") out += "\\'";
    else out += ch;
  }
  return out + "'";
}

const input = process.argv[2];
try {
  console.log(show(safeLoad(input)));
} catch (err) {
  console.log('ERR ' + err.constructor.name + ': ' + (err.toString ? err.toString() : err.message));
}

