      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = LINEBR_CHARS.includes(ch);
      }
      end += 1;
    }
    this.writeIndicator("'", false);
  }

  writeDoubleQuoted(textStr, split = true) {
    this.writeIndicator('"', true);
    const text = cps(textStr);
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
