        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeLiteral(textStr) {
    const text = cps(textStr);
    const hints = this.determineBlockHints(text);
    this.writeIndicator('|' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= text.length) {
      let ch = null;
      if (end < text.length) ch = text[end];
      if (breaks) {
        if (ch === null || !LINEBR_CHARS.includes(ch)) {
          for (const br of text.slice(start, end)) {
