// Python values -> node graph, ported from PyYAML's representer.py
// (BaseRepresenter + SafeRepresenter + the tuple support of Representer,
// which is what yaml.dump uses).

import { RepresenterError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import {
  PyBytes, PyTuple, PyDict, PySet, PyDate, PyDateTime,
  pyFloatRepr, pyLess, pyEqual, pySorted, PyTypeError, typeName,
} from './pytypes.mjs';

const T = {
  null: 'tag:yaml.org,2002:null',
  bool: 'tag:yaml.org,2002:bool',
  int: 'tag:yaml.org,2002:int',
  float: 'tag:yaml.org,2002:float',
  str: 'tag:yaml.org,2002:str',
  binary: 'tag:yaml.org,2002:binary',
  seq: 'tag:yaml.org,2002:seq',
  map: 'tag:yaml.org,2002:map',
  set: 'tag:yaml.org,2002:set',
  timestamp: 'tag:yaml.org,2002:timestamp',
  tuple: 'tag:yaml.org,2002:python/tuple',
};

export class Representer {
  constructor(serializer, options = {}) {
    this.serializer = serializer;
    this.defaultStyle = options.defaultStyle === undefined ? null : options.defaultStyle;
    this.defaultFlowStyle = options.defaultFlowStyle === undefined
      ? false : options.defaultFlowStyle;
    this.sortKeys = options.sortKeys === undefined ? true : options.sortKeys;
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  represent(data) {
    const node = this.representData(data);
    this.serializer.serialize(node);
    this.representedObjects = new Map();
    this.aliasKey = null;
  }

  ignoreAliases(data) {
    if (data === null) return true;
    if (data instanceof PyTuple && data.items.length === 0) return true;
    return typeof data === 'string' || typeof data === 'boolean' ||
      typeof data === 'bigint' || typeof data === 'number' ||
      data instanceof PyBytes;
  }

  representData(data) {
    this.aliasKey = this.ignoreAliases(data) ? null : data;
    if (this.aliasKey !== null) {
      if (this.representedObjects.has(this.aliasKey)) {
        return this.representedObjects.get(this.aliasKey);
      }
    }
    if (data === null) return this.representNone();
    if (typeof data === 'string') return this.representStr(data);
    if (typeof data === 'boolean') return this.representBool(data);
    if (typeof data === 'bigint') return this.representInt(data);
    if (typeof data === 'number') return this.representFloat(data);
    if (data instanceof PyBytes) return this.representBinary(data);
    if (Array.isArray(data)) return this.representList(data);
    if (data instanceof PyTuple) return this.representTuple(data);
    if (data instanceof PyDict) return this.representDict(data);
    if (data instanceof PySet) return this.representSet(data);
    if (data instanceof PyDateTime) return this.representDatetime(data);
    if (data instanceof PyDate) return this.representDate(data);
    return this.representUndefined(data);
  }

  representScalar(tag, value, style = null) {
    const useStyle = style === null ? this.defaultStyle : style;
    const node = new ScalarNode(tag, value, null, null, useStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    return node;
  }

  representSequence(tag, sequence, flowStyle = null) {
    const value = [];
    const node = new SequenceNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    for (const item of sequence) {
      const nodeItem = this.representData(item);
      if (!(nodeItem.kind === 'scalar' && !nodeItem.style)) bestStyle = false;
      value.push(nodeItem);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle !== null ? this.defaultFlowStyle : bestStyle;
    }
    return node;
  }

  representMapping(tag, mapping, flowStyle = null) {
    const value = [];
    const node = new MappingNode(tag, value, null, null, flowStyle);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    let bestStyle = true;
    let items = mapping instanceof PyDict ? mapping.items() : mapping;
    if (mapping instanceof PyDict && this.sortKeys) {
      try {
        items = pySorted(items, itemLess);
      } catch (err) {
        if (!(err instanceof PyTypeError)) throw err;
      }
    }
    for (const [itemKey, itemValue] of items) {
      const nodeKey = this.representData(itemKey);
      const nodeValue = this.representData(itemValue);
      if (!(nodeKey.kind === 'scalar' && !nodeKey.style)) bestStyle = false;
      if (!(nodeValue.kind === 'scalar' && !nodeValue.style)) bestStyle = false;
      value.push([nodeKey, nodeValue]);
    }
    if (flowStyle === null) {
      node.flowStyle = this.defaultFlowStyle !== null ? this.defaultFlowStyle : bestStyle;
    }
    return node;
  }

  // -- type representers ---------------------------------------------------

  representNone() { return this.representScalar(T.null, 'null'); }

  representStr(data) { return this.representScalar(T.str, data); }

  representBool(data) {
    return this.representScalar(T.bool, data ? 'true' : 'false');
  }

  representInt(data) { return this.representScalar(T.int, data.toString()); }

  representFloat(data) {
    let value;
    if (Number.isNaN(data)) value = '.nan';
    else if (data === Infinity) value = '.inf';
    else if (data === -Infinity) value = '-.inf';
    else {
      value = pyFloatRepr(data).toLowerCase();
      if (!value.includes('.') && value.includes('e')) {
