      }
    }
    return this.representScalar(T.float, value);
  }

  representBinary(data) {
    return this.representScalar(T.binary, base64Encode(data.bytes), '|');
  }

  representList(data) { return this.representSequence(T.seq, data); }

  representTuple(data) { return this.representSequence(T.tuple, data.items); }

  representDict(data) { return this.representMapping(T.map, data); }

  representSet(data) {
    const value = new PyDict();
    for (const key of data.values()) value.set(key, null);
    return this.representMapping(T.set, value);
  }

  representDate(data) {
    return this.representScalar(T.timestamp, data.isoformat());
  }

  representDatetime(data) {
    return this.representScalar(T.timestamp, data.isoformat(' '));
  }

  representUndefined(data) {
    throw new RepresenterError(`cannot represent an object: ${typeName(data)}`);
  }
}

// sorted() on a list of (key, value) tuples.
function itemLess(a, b) {
  if (!pyEqual(a[0], b[0])) return pyLess(a[0], b[0]);
  return pyLess(a[1], b[1]);
}

const B64_ALPHABET =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

// base64.encodebytes(): 76-character lines, trailing newline.
function base64Encode(bytes) {
  let raw = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    const bits = (b0 << 16) | (b1 << 8) | b2;
    raw += B64_ALPHABET[(bits >> 18) & 63];
    raw += B64_ALPHABET[(bits >> 12) & 63];
    raw += i + 1 < bytes.length ? B64_ALPHABET[(bits >> 6) & 63] : '=';
    raw += i + 2 < bytes.length ? B64_ALPHABET[bits & 63] : '=';
  }
  let out = '';
  for (let i = 0; i < raw.length; i += 76) out += raw.slice(i, i + 76) + '\n';
  return out;
}

