// Dumper wiring: Python value -> YAML text (equivalent of yaml.dump).

import { Emitter } from './emitter.mjs';
import { Resolver } from './resolver.mjs';
import { Serializer } from './serializer.mjs';
import { Representer } from './representer.mjs';

class StringStream {
  constructor() {
    this.chunks = [];
  }

  write(data) { this.chunks.push(data); }

  getValue() { return this.chunks.join(''); }
}

export function dump(data, options = {}) {
  const stream = new StringStream();
  const emitter = new Emitter(stream, options);
  const resolver = new Resolver();
  const serializer = new Serializer(emitter, resolver, options);
  const representer = new Representer(serializer, {
    defaultStyle: options.defaultStyle === undefined ? null : options.defaultStyle,
    defaultFlowStyle: options.defaultFlowStyle === undefined
      ? false : options.defaultFlowStyle,
    sortKeys: options.sortKeys === undefined ? true : options.sortKeys,
  });
  serializer.open();
  representer.represent(data);
  serializer.close();
  return stream.getValue();
}

