// A focused port of the pieces of Python's argparse that this CLI exercises:
// long-option abbreviation, '--opt=value', negative-number values, required
// checks, extras reporting, and argparse's exact usage/help/error formatting.

export class ArgumentError extends Error {}

class Action {
  constructor(optionStrings, dest, nargs, help, required, metavar) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs; // 0 for flags, 1 for single-value options
    this.help = help;
    this.required = required;
    this.metavar = metavar;
  }

  get invocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return this.optionStrings.map((s) => `${s} ${this.metavar}`).join(', ');
  }
}

const NEGATIVE_NUMBER = (s) => {
  // ^-\d+$|^-\d*\.\d+$
  if (s[0] !== '-') return false;
  const body = s.slice(1);
  if (!body.length) return false;
  let seenDot = false;
  let digitsAfterDot = 0;
  let digitsBeforeDot = 0;
  for (const ch of body) {
    if (ch === '.') {
      if (seenDot) return false;
      seenDot = true;
    } else if (ch >= '0' && ch <= '9') {
      if (seenDot) digitsAfterDot += 1;
      else digitsBeforeDot += 1;
    } else {
      return false;
    }
  }
  if (!seenDot) return digitsBeforeDot > 0;
  return digitsAfterDot > 0;
};

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      dest: 'help', nargs: 0, help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest = options.dest || optionStrings[optionStrings.length - 1]
      .replace(/^-+/, '');
    const action = new Action(optionStrings, dest,
      options.nargs === undefined ? 1 : options.nargs,
      options.help === undefined ? null : options.help,
      !!options.required,
